// Alt text and responsive sources for the course photos in public/course-images.
//
// The catalogue data files (generated by scripts/sync-public-course-catalogue.ps1) only carry the
// course title as alt text, which duplicates the heading next to every image. These descriptions
// say what the photograph actually shows. Keyed by course slug (the file name without extension).
// tests/course-images.test.mjs fails if a course image has no entry or is missing its WebP files.

export const COURSE_IMAGE_ALT: Record<string, string> = {
  "certification-in-advance-machine-procedures-in-cosmetology": "A smiling woman lies back while a practitioner in pink gloves treats her neck with a handheld skin device",
  "certification-in-advanced-endodontics": "A dentist treats a smiling patient's open mouth with a dental handpiece",
  "certification-in-advanced-laser-cosmetology": "A patient in eye protection with a dark carbon mask on her face has a laser handpiece applied to her skin",
  "certification-in-aesthetic-dentistry": "A patient in red protective glasses has her teeth treated with a handheld blue-light device by a masked clinician",
  "certification-in-chemical-peels": "A woman in a headband has a peel solution brushed onto her forehead",
  "certification-in-hair-restoration-removal-medical": "A woman in dark protective goggles has laser hair removal on her underarm with a handheld device",
  "certification-in-injectables-medical": "A woman in a headband receives an injection near her lip from a practitioner in pink gloves",
  "certification-in-micropigmentation-non-medical": "A woman with closed eyes has pigment applied to her lips with a pen-style device",
  "fellowship-in-facial-aesthetics-fifa": "A woman with closed eyes receives a facial injection beside her eye from gloved hands",
  "fellowship-in-trichology": "A man lies back while gloved hands give an injection at his hairline",
  "international-fellowship-in-facial-aesthetics": "A practitioner marks guide lines in blue pen on a woman's cheek and jaw before a facial treatment",
  "msc-in-aesthetic-nursing": "Four smiling healthcare professionals in scrubs and white coats stand together",
  "msc-in-cosmetology-non-medical": "A beautician applies a white facial mask to a woman wrapped in a towel",
  "msc-in-facial-aesthetics": "A gloved practitioner holds a syringe near the lips of a woman with dark curly hair",
  "post-graduate-diploma-in-clinical-cosmetology-medical": "A woman in a headband has a pen-shaped treatment device applied to her forehead by a gloved practitioner",
  "post-graduate-diploma-in-clinical-cosmetology-non-medical": "A woman lies back while a practitioner uses a handheld device along her jaw",
};

const COURSE_IMAGE_PATH = /^(\/course-images\/)([^/]+)\.(jpe?g|png)$/i;
export const COURSE_IMAGE_WIDTHS = [640, 1300] as const;

export function courseImageSlug(src: string): string | null {
  return COURSE_IMAGE_PATH.exec(src)?.[2] ?? null;
}

/** Alt text for a course image: the written description, else the supplied fallback. */
export function courseImageAlt(src: string, fallback: string): string {
  const slug = courseImageSlug(src);
  return (slug && COURSE_IMAGE_ALT[slug]) || fallback;
}

/** WebP srcset for a course image, or undefined for any other path. */
export function courseImageSrcSet(src: string): string | undefined {
  const match = COURSE_IMAGE_PATH.exec(src);
  if (!match) return undefined;
  return COURSE_IMAGE_WIDTHS.map((width) => `${match[1]}${match[2]}-${width}.webp ${width}w`).join(", ");
}
